1	/**
2	 * Drains pending webhook deliveries with exponential backoff; disabled unless the org's plan includes webhooks.
3	 *
4	 * Must call (do not reimplement): isEnabled, getPlanLimits, signPayload
5	 */
6	import { getPlanLimits } from "@/config/plan-limits";
7	import { isEnabled } from "@/lib/feature-flags";
8	import { createLogger } from "@/lib/logger";
9	import * as orgRepo from "@/server/repositories/organization-repository";
10	import * as webhookRepo from "@/server/repositories/webhook-repository";
11	import { buildFlagContext } from "@/server/services/feature-flag-service";
12	import { signPayload } from "@/server/services/webhook-service";
13	import { toIsoTimestamp } from "@/types/common";
14	import { runJob } from "./types";
15	import type { JobResult } from "@/server/jobs/types";
16	import type { OrgId } from "@/types/common";
17	
18	/** How many deliveries one pass claims. */
19	const CLAIM_BATCH = 25;
20	
21	/** Attempts after which a delivery is marked failed for good. */
22	const MAX_ATTEMPTS = 6;
23	
24	const logger = createLogger("webhook-delivery-job");
25	
26	/**
27	 * Delivers each claimed row. There is no outbound HTTP in Taskflow — the
28	 * corpus builds and runs offline — so "delivery" means computing the
29	 * signature the receiver would verify and logging the attempt. The retry
30	 * bookkeeping around it is the part that has to be right.
31	 */
32	export async function runWebhookDeliveryJob(now: Date): Promise<JobResult> {
33	  return runJob("webhook-delivery", async (result) => {
34	    const claimed = await webhookRepo.claimPendingDeliveries(CLAIM_BATCH);
35	
36	    for (const delivery of claimed) {
37	      const orgId = delivery.orgId as OrgId;
38	
39	      if (!(await orgAllowsWebhooks(orgId))) {
40	        await webhookRepo.markDeliveryFailed(
41	          orgId,
42	          delivery.id,
43	          "webhooks are not included in this organization's plan",
44	        );
45	        result.failed += 1;
46	        continue;
47	      }
48	
49	      if (delivery.attempts > MAX_ATTEMPTS) {
50	        await webhookRepo.markDeliveryFailed(
51	          orgId,
52	          delivery.id,
53	          `giving up after ${delivery.attempts} attempts`,
54	        );
55	        result.failed += 1;
56	        continue;
57	      }
58	
59	      const endpoint = (await webhookRepo.listEndpoints(orgId)).find(
60	        (row) => row.id === delivery.endpointId,
61	      );
62	
63	      if (!endpoint || !endpoint.enabled) {
64	        await webhookRepo.markDeliveryFailed(
65	          orgId,
66	          delivery.id,
67	          "endpoint is missing or disabled",
68	        );
69	        result.failed += 1;
70	        continue;
71	      }
72	
73	      const signature = signPayload(endpoint.secret, delivery.payload);
74	
75	      logger.info("webhook delivered", {
76	        deliveryId: delivery.id,
77	        endpoint: endpoint.url,
78	        eventType: delivery.eventType,
79	        signature: signature.slice(0, 16),
80	        backoffMs: backoffMs(delivery.attempts),
81	      });
82	
83	      await webhookRepo.markDelivered(orgId, delivery.id, toIsoTimestamp(now));
84	      result.processed += 1;
85	    }
86	  });
87	}
88	
89	/** 1s, 2s, 4s … capped at five minutes; attempt 0 retries immediately. */
90	export function backoffMs(attempts: number): number {
91	  if (attempts <= 0) return 0;
92	  return Math.min(300_000, 2 ** (attempts - 1) * 1_000);
93	}
94	
95	async function orgAllowsWebhooks(orgId: OrgId): Promise<boolean> {
96	  const org = await orgRepo.findOrgById(orgId);
97	  if (!org) return false;
98	
99	  if (getPlanLimits(org.plan).webhooks <= 0) return false;
100	  return isEnabled("webhooks", buildFlagContext(null, org));
101	}
102

